INSERT INTO trips (id, slug, title, city_id, location_label, category_id, duration_label, duration_minutes, description, image_url, price_from, currency, rating, review_count, is_featured, is_active, solo_price, discount_percent, price_level, source_type, catalog_visible, metadata) VALUES ('b45c448f-822f-4aa3-9e02-02ab08f81c62', 'day-tour-to-edfu-temple-and-kom-ombo-temple-from-aswan', 'Day Tour to Edfu Temple and Kom Ombo Temple from Aswan', (SELECT id FROM cities WHERE slug = 'aswan' LIMIT 1), 'Aswan', (SELECT id FROM trip_categories WHERE slug = 'adventure-trips' LIMIT 1), '1 day', 1440, 'Enjoy a full day of ancient wonders on this day trip to Edfu and Kom Ombo from Aswan! There’s no better way to experience the timeless beauty of the River Nile than by visiting these two magnificent temples located right by the riverbanks. Start with the grand Temple of Horus at Edfu, one of the best-preserved shrines in Egypt, followed by a visit to Kom Ombo, the unique double temple dedicated to Sobek (the Crocodile God) and Haroeris (an aspect of Horus).', '/trips/day-tour-edfu-kom-ombo.png', 57, 'USD', 4.7, 3, 0, 1, 87, 10, 'Economy', 'legacy', 1, '{"source":"legacyCatalog","sourceCities":["Aswan"],"sourceCategories":["Adventure Trips","Historical","One Day Trips"]}') ON DUPLICATE KEY UPDATE title = VALUES(title), city_id = VALUES(city_id), location_label = VALUES(location_label), category_id = VALUES(category_id), duration_label = VALUES(duration_label), duration_minutes = VALUES(duration_minutes), description = VALUES(description), image_url = VALUES(image_url), price_from = VALUES(price_from), currency = VALUES(currency), rating = VALUES(rating), review_count = VALUES(review_count), is_featured = VALUES(is_featured), is_active = 1, solo_price = VALUES(solo_price), discount_percent = VALUES(discount_percent), price_level = VALUES(price_level), source_type = VALUES(source_type), catalog_visible = VALUES(catalog_visible), metadata = VALUES(metadata);
INSERT INTO trip_day_plans (trip_id, day_number, activities) VALUES ((SELECT id FROM trips WHERE slug = 'day-tour-to-edfu-temple-and-kom-ombo-temple-from-aswan' LIMIT 1), 1, '[{"time":"08:00","title":"Pick up from Aswan hotel"},{"time":"09:30","title":"Guided tour of Edfu Temple (Temple of Horus)"},{"time":"12:30","title":"Lunch break by the Nile"},{"time":"14:00","title":"Guided tour of Kom Ombo Temple (Sobek & Haroeris)"},{"time":"17:00","title":"Return to Aswan"}]') ON DUPLICATE KEY UPDATE activities = VALUES(activities);
