INSERT INTO trips (id, slug, title, city_id, location_label, category_id, duration_label, duration_minutes, description, image_url, price_from, currency, rating, review_count, is_featured, is_active, solo_price, discount_percent, price_level, source_type, catalog_visible, metadata) VALUES ('4ab8e7d9-d794-4646-9407-10a15f58e688', 'day-tour-to-dendera-and-abydos-temples-from-hurghada', 'Day Tour to Dendera and Abydos Temples from Hurghada', (SELECT id FROM cities WHERE slug = 'luxor' LIMIT 1), 'Luxor · Hurghada', (SELECT id FROM trip_categories WHERE slug = 'one-day-trips' LIMIT 1), '1 day', 1440, 'Embark on a cultural journey from Hurghada to the historic temples of Dendera and Abydos. Begin with a visit to the beautifully preserved Temple of Hathor at Dendera, dedicated to the goddess of love, music, and healing. Then continue to Abydos, a holy pilgrimage site in Ancient Egypt, to explore the majestic Temple of Seti I, home to the famous Abydos King List. Travel in comfort with an Egyptologist guide and enjoy lunch at a local restaurant before returning to Hurghada.', '/trips/dendera-abydos-from-hurghada.png', 88, 'USD', 5, 1, 0, 1, 127, 30, 'Standard', 'legacy', 1, '{"source":"legacyCatalog","sourceCities":["Luxor","Hurghada"],"sourceCategories":["One Day Trips","Family Friendly","Historical"]}') ON DUPLICATE KEY UPDATE title = VALUES(title), city_id = VALUES(city_id), location_label = VALUES(location_label), category_id = VALUES(category_id), duration_label = VALUES(duration_label), duration_minutes = VALUES(duration_minutes), description = VALUES(description), image_url = VALUES(image_url), price_from = VALUES(price_from), currency = VALUES(currency), rating = VALUES(rating), review_count = VALUES(review_count), is_featured = VALUES(is_featured), is_active = 1, solo_price = VALUES(solo_price), discount_percent = VALUES(discount_percent), price_level = VALUES(price_level), source_type = VALUES(source_type), catalog_visible = VALUES(catalog_visible), metadata = VALUES(metadata);
INSERT INTO trip_day_plans (trip_id, day_number, activities) VALUES ((SELECT id FROM trips WHERE slug = 'day-tour-to-dendera-and-abydos-temples-from-hurghada' LIMIT 1), 1, '[{"time":"06:00","title":"Pick up from Hurghada hotel"},{"time":"08:30","title":"Drive to Dendera Temple (Temple of Hathor)"},{"time":"11:00","title":"Guided tour of the Temple of Hathor"},{"time":"12:30","title":"Lunch at a local restaurant"},{"time":"14:00","title":"Continue to Abydos Temple (Temple of Seti I)"},{"time":"15:00","title":"Guided tour of Abydos Temple & King List"},{"time":"17:00","title":"Return journey to Hurghada"},{"time":"20:00","title":"Drop off at Hurghada hotel"}]') ON DUPLICATE KEY UPDATE activities = VALUES(activities);
