INSERT INTO trips (id, slug, title, city_id, location_label, category_id, duration_label, duration_minutes, description, image_url, price_from, currency, rating, review_count, is_featured, is_active, solo_price, discount_percent, price_level, source_type, catalog_visible, metadata) VALUES ('036a8012-6821-43c7-a96f-14df97af0dc1', 'luxor-guided-tour-to-valley-of-the-kings-hatshepsut-temple-habu-temple-colossi-o', 'Luxor: Guided Tour to Valley of the Kings, Hatshepsut Temple, Habu Temple & Colossi of Memnon', (SELECT id FROM cities WHERE slug = 'luxor' LIMIT 1), 'Luxor', (SELECT id FROM trip_categories WHERE slug = 'spiritual' LIMIT 1), '1 day', 1440, 'Discover the wonders of the West Bank of Luxor on this guided tour to some of ancient Egypt’s most iconic landmarks. Explore the Valley of the Kings, the beautifully preserved Hatshepsut Temple, the richly decorated Medinet Habu Temple, and the imposing Colossi of Memnon. Learn all about the legends, history, and architecture from your multilingual Egyptologist guide.', '/trips/luxor-west-bank-heritage.png', 52, 'USD', NULL, 0, 0, 1, 72, 0, 'Economy', 'legacy', 1, '{"source":"legacyCatalog","sourceCities":["Luxor"],"sourceCategories":["Spiritual","Historical","One Day Trips","Family Friendly"]}') ON DUPLICATE KEY UPDATE title = VALUES(title), city_id = VALUES(city_id), location_label = VALUES(location_label), category_id = VALUES(category_id), duration_label = VALUES(duration_label), duration_minutes = VALUES(duration_minutes), description = VALUES(description), image_url = VALUES(image_url), price_from = VALUES(price_from), currency = VALUES(currency), rating = VALUES(rating), review_count = VALUES(review_count), is_featured = VALUES(is_featured), is_active = 1, solo_price = VALUES(solo_price), discount_percent = VALUES(discount_percent), price_level = VALUES(price_level), source_type = VALUES(source_type), catalog_visible = VALUES(catalog_visible), metadata = VALUES(metadata);
