INSERT INTO trip_inclusions (trip_id, item, sort_order) VALUES ((SELECT id FROM trips WHERE slug = 'luxor-guided-tour-to-valley-of-the-kings-hatshepsut-temple-habu-temple-colossi-o' LIMIT 1), 'Private, air‑conditioned transportation from/to Luxor', 2) ON DUPLICATE KEY UPDATE sort_order = VALUES(sort_order);
INSERT INTO trips (id, slug, title, city_id, location_label, category_id, duration_label, duration_minutes, description, image_url, price_from, currency, rating, review_count, is_featured, is_active, solo_price, discount_percent, price_level, source_type, catalog_visible, metadata) VALUES ('2935ee95-29d9-48a7-9024-1eb82f6e6f1a', 'hurghada-city-tour-with-shopping-stop', 'Hurghada City Tour with Shopping Stop', (SELECT id FROM cities WHERE slug = 'hurghada' LIMIT 1), 'Hurghada', (SELECT id FROM trip_categories WHERE slug = 'one-day-trips' LIMIT 1), '1 day', 1440, 'Step away from the beach and dive into the vibrant culture and history of Hurghada, one of Egypt’s most fascinating Red Sea cities. This panoramic city tour combines culture, local life, and shopping in a relaxed and insightful half-day experience. Your journey begins with a pickup from your hotel, where you’ll meet your guide and set off on a comfortable drive through the city. Your first stop is the Coptic Orthodox Church, a peaceful and ornate place of worship that offers a glimpse into Egypt’s Christian heritage. Spend some quiet time here exploring its beautiful interior and surroundings. Next, you’ll head to a lively local vegetable market, where colorful stalls brim with fresh produce and fragrant herbs. Walk among locals, experience the bustle, and see how everyday life unfolds in Hurghada beyond the tourist resorts. The tour continues with a shopping experience at some of the city’s top gift and souvenir shops, where you can browse for handcrafted items, traditional Egyptian goods, and keepsakes. After shopping, you''ll visit one of Hurghada''s iconic landmarks — the Grand Mosque. Take in its impressive architecture and serene surroundings while learning about Islamic traditions and local religious practices. Finally, enjoy a relaxing walk at the New Marina, a stylish and modern waterfront area recently renovated to become one of the city’s main attractions. With its scenic views, luxury yachts, and lively cafés, the marina is a perfect spot to unwind before heading back to your hotel.', '/trips/hurghada-city-local-life.png', 22, 'USD', 5, 1, 0, 1, 37, 40, 'Economy', 'legacy', 1, '{"source":"legacyCatalog","sourceCities":["Hurghada"],"sourceCategories":["One Day Trips","Family Friendly","Adventure Trips"]}') ON DUPLICATE KEY UPDATE title = VALUES(title), city_id = VALUES(city_id), location_label = VALUES(location_label), category_id = VALUES(category_id), duration_label = VALUES(duration_label), duration_minutes = VALUES(duration_minutes), description = VALUES(description), image_url = VALUES(image_url), price_from = VALUES(price_from), currency = VALUES(currency), rating = VALUES(rating), review_count = VALUES(review_count), is_featured = VALUES(is_featured), is_active = 1, solo_price = VALUES(solo_price), discount_percent = VALUES(discount_percent), price_level = VALUES(price_level), source_type = VALUES(source_type), catalog_visible = VALUES(catalog_visible), metadata = VALUES(metadata);
INSERT INTO trip_day_plans (trip_id, day_number, activities) VALUES ((SELECT id FROM trips WHERE slug = 'hurghada-city-tour-with-shopping-stop' LIMIT 1), 1, '[{"time":"09:00","title":"Hotel Pick‑up   Meet your guide and driver at your Hurghada hotel."},{"time":"11:45","title":"Traditional Market & Shopping Stop   Browse souvenirs, spices, handicrafts, and jewelry in the bustling bazaar"},{"time":"12:45","title":" Local Café Break   Relax with Egyptian tea or fresh juice."},{"time":"09:30","title":" Hurghada Marina & Old Port   Stroll along the marina, see fishing boats, and enjoy the Red Sea views."},{"time":"10:45","title":"Visit El Mina Mosque   Explore Hurghada’s largest mosque, admire its architecture, and learn about local traditions."}]') ON DUPLICATE KEY UPDATE activities = VALUES(activities);
