INSERT INTO trips (id, slug, title, city_id, location_label, category_id, duration_label, duration_minutes, description, image_url, price_from, currency, rating, review_count, is_featured, is_active, solo_price, discount_percent, price_level, source_type, catalog_visible, metadata) VALUES ('b94772cf-035a-4060-8761-22bfe4c88360', 'tour-of-the-banana-island-with-a-felucca-experience-from-luxor', 'Tour of Banana Island with a Felucca Experience from Luxor', (SELECT id FROM cities WHERE slug = 'luxor' LIMIT 1), 'Luxor', (SELECT id FROM trip_categories WHERE slug = 'family-friendly' LIMIT 1), '1 day', 1440, 'Discover Banana Island and the Nile on this three-hour guided tour whilst experiencing being on a "felucca" at sunset. Starting from your pickup you''ll travel to meet your "felucca" traditional wooden boat with your local guide. As you glide along the Nile passing hotels, houses and monuments, you''ll see the sun setting behind the mountains of Luxor and feel your body relax as you continue to Banana Island or "Gezerit El Moze". Next, at the island, you''ll marvel at the banana trees, and taste bananas straight from the tree given to you by the local farmers. You''ll also learn about its importance and history from your local guide to complete your experience.', '/trips/banana-island-felucca-luxor.png', 27, 'USD', 5, 3, 0, 1, 42, 40, 'Economy', 'legacy', 1, '{"source":"legacyCatalog","sourceCities":["Luxor"],"sourceCategories":["Family Friendly"]}') ON DUPLICATE KEY UPDATE title = VALUES(title), city_id = VALUES(city_id), location_label = VALUES(location_label), category_id = VALUES(category_id), duration_label = VALUES(duration_label), duration_minutes = VALUES(duration_minutes), description = VALUES(description), image_url = VALUES(image_url), price_from = VALUES(price_from), currency = VALUES(currency), rating = VALUES(rating), review_count = VALUES(review_count), is_featured = VALUES(is_featured), is_active = 1, solo_price = VALUES(solo_price), discount_percent = VALUES(discount_percent), price_level = VALUES(price_level), source_type = VALUES(source_type), catalog_visible = VALUES(catalog_visible), metadata = VALUES(metadata);
INSERT INTO trip_day_plans (trip_id, day_number, activities) VALUES ((SELECT id FROM trips WHERE slug = 'tour-of-the-banana-island-with-a-felucca-experience-from-luxor' LIMIT 1), 1, '[{"time":"18:15","title":"Arrive at Banana Island and walk through the banana plantations. Learn how bananas are grown, meet local farmers, and taste fresh bananas picked directly from the trees. Your guide explains the island’s history and its importance to Luxor’s agriculture."}]') ON DUPLICATE KEY UPDATE activities = VALUES(activities);
