INSERT INTO trips (id, slug, title, city_id, location_label, category_id, duration_label, duration_minutes, description, image_url, price_from, currency, rating, review_count, is_featured, is_active, solo_price, discount_percent, price_level, source_type, catalog_visible, metadata) VALUES ('8ddb3cd5-5292-4c78-a6e1-33409fc59d6d', '4-day-all-inclusive-lake-nasser-cruise-abu-simbel-to-aswan', '4-Day All-Inclusive Lake Nasser Cruise – Abu Simbel to Aswan', (SELECT id FROM cities WHERE slug = 'aswan' LIMIT 1), 'Aswan', (SELECT id FROM trip_categories WHERE slug = 'luxury-tours' LIMIT 1), '4 days', 5760, 'Discover the wonders of ancient Nubia and the charm of Lake Nasser in a luxurious 4-day cruise from Abu Simbel to Aswan. With guided tours, all meals, and accommodations included, this is the ultimate way to dive into Egypt’s majestic past, visiting temples like Abu Simbel, Amada, Wadi el Seboua, and Kalabsha.', '/trips/lake-nasser-abu-simbel-cruise.png', 397, 'USD', NULL, 0, 0, 1, 497, 0, 'Luxury', 'legacy', 1, '{"source":"legacyCatalog","sourceCities":["Aswan"],"sourceCategories":["Luxury Tours","Family Friendly","Historical","Adventure Trips","Nile Cruises"]}') ON DUPLICATE KEY UPDATE title = VALUES(title), city_id = VALUES(city_id), location_label = VALUES(location_label), category_id = VALUES(category_id), duration_label = VALUES(duration_label), duration_minutes = VALUES(duration_minutes), description = VALUES(description), image_url = VALUES(image_url), price_from = VALUES(price_from), currency = VALUES(currency), rating = VALUES(rating), review_count = VALUES(review_count), is_featured = VALUES(is_featured), is_active = 1, solo_price = VALUES(solo_price), discount_percent = VALUES(discount_percent), price_level = VALUES(price_level), source_type = VALUES(source_type), catalog_visible = VALUES(catalog_visible), metadata = VALUES(metadata);
