INSERT INTO trips (id, slug, title, city_id, location_label, category_id, duration_label, duration_minutes, description, image_url, price_from, currency, rating, review_count, is_featured, is_active, solo_price, discount_percent, price_level, source_type, catalog_visible, metadata) VALUES ('31c9297b-c1c4-4e3b-b004-34fd8f10f4f9', 'luxor-deluxe-guided-tour-from-hurghada', 'Luxor Deluxe Guided Tour from Hurghada', (SELECT id FROM cities WHERE slug = 'hurghada' LIMIT 1), 'Hurghada · Luxor', (SELECT id FROM trip_categories WHERE slug = 'historical' LIMIT 1), '1 day', 1440, 'Discover one of the world''s greatest open-air museums including Karnak Temple, the Valley of the Kings and the Temple of the Queen Hatshepsut on this semi-private tour for small groups of up to 8 pax. Get picked up in the early morning from your accommodation in Hurghada, El Gouna, Makadi, Soma Bay, Safaga or Kalawy Bay and set off to Luxor. The first sight will be the impressive Karnak Temple, a sprawling complex of towering temples. Next, you’ll have a set menu lunch at a 5-star hotel to meet your expectations before heading to the Valley of the Kings. You’ll get to enter three of its 63 royal tombs. Then, take in the ancient Mortuary Temple of Hatshepsut, and the staggering Colossi of Memnon, where you will have a jam-packed day of temples, tombs, and monuments that sweep you through thousands of years of history. Drive back to your accommodation in Hurghada with unforgettable memories.', '/trips/luxor-deluxe-temples.png', 92, 'USD', NULL, 0, 0, 1, 127, 0, 'Economy', 'legacy', 1, '{"source":"legacyCatalog","sourceCities":["Hurghada","Luxor"],"sourceCategories":["Historical","One Day Trips","Spiritual"]}') ON DUPLICATE KEY UPDATE title = VALUES(title), city_id = VALUES(city_id), location_label = VALUES(location_label), category_id = VALUES(category_id), duration_label = VALUES(duration_label), duration_minutes = VALUES(duration_minutes), description = VALUES(description), image_url = VALUES(image_url), price_from = VALUES(price_from), currency = VALUES(currency), rating = VALUES(rating), review_count = VALUES(review_count), is_featured = VALUES(is_featured), is_active = 1, solo_price = VALUES(solo_price), discount_percent = VALUES(discount_percent), price_level = VALUES(price_level), source_type = VALUES(source_type), catalog_visible = VALUES(catalog_visible), metadata = VALUES(metadata);
INSERT INTO trip_day_plans (trip_id, day_number, activities) VALUES ((SELECT id FROM trips WHERE slug = 'luxor-deluxe-guided-tour-from-hurghada' LIMIT 1), 1, '[{"time":"13:30","title":"Valley of the Kings   Enter 3 royal tombs, including those of Ramses and optionally Tutankhamun. Learn about the “Place of Truth.”"},{"time":"16:45","title":"Return Drive to Hurghada   Relax on the journey back."}]') ON DUPLICATE KEY UPDATE activities = VALUES(activities);
