INSERT INTO trips (id, slug, title, city_id, location_label, category_id, duration_label, duration_minutes, description, image_url, price_from, currency, rating, review_count, is_featured, is_active, solo_price, discount_percent, price_level, source_type, catalog_visible, metadata) VALUES ('5d446bbf-6ac1-4172-a7de-5f906b663a05', 'explore-the-nubian-village-by-traditional-felucca-plus-authentic-lunch', 'Explore the Nubian Village by traditional felucca plus authentic lunch', (SELECT id FROM cities WHERE slug = 'aswan' LIMIT 1), 'Aswan', (SELECT id FROM trip_categories WHERE slug = 'historical' LIMIT 1), '1 day', 1440, 'Meet the residents of the Nubian villages, known to be extremely friendly and hospitable, listen to their native language, Nuba. Visit their traditional Nubian village, with vividly colored houses, spice shops and cafes overlooking the Nile River. Get picked up from your hotel, or your Nile cruise ship and head to the Nile dock. Embark onboard a motorboat to the Nubian Village; here you have time for a tour around the village, located on an island. In the village you are also going to taste a delicious authentic homemade lunch featuring a lovely type of green and white salad, called tahina, in addition to some rice and freshly baked bread. After the restorative lunch, you will sail the Nile on a traditional felucca, a canvas-sailed boat typical of this river. The Nile is at its most picturesque in Aswan, admire the landscape around you while sipping a freshly made tea served to you by the felucca’s captain.', '/trips/explore-the-nubian-village-by-traditional-felucca-plus-authentic-lunch.png', 37, 'USD', NULL, 0, 0, 1, 57, 0, 'Economy', 'legacy', 1, '{"source":"legacyCatalog","sourceCities":["Aswan"],"sourceCategories":["Historical","Family Friendly","One Day Trips","Adventure Trips"]}') ON DUPLICATE KEY UPDATE title = VALUES(title), city_id = VALUES(city_id), location_label = VALUES(location_label), category_id = VALUES(category_id), duration_label = VALUES(duration_label), duration_minutes = VALUES(duration_minutes), description = VALUES(description), image_url = VALUES(image_url), price_from = VALUES(price_from), currency = VALUES(currency), rating = VALUES(rating), review_count = VALUES(review_count), is_featured = VALUES(is_featured), is_active = 1, solo_price = VALUES(solo_price), discount_percent = VALUES(discount_percent), price_level = VALUES(price_level), source_type = VALUES(source_type), catalog_visible = VALUES(catalog_visible), metadata = VALUES(metadata);
