INSERT INTO trips (id, slug, title, city_id, location_label, category_id, duration_label, duration_minutes, description, image_url, price_from, currency, rating, review_count, is_featured, is_active, solo_price, discount_percent, price_level, source_type, catalog_visible, metadata) VALUES ('63fe4466-3a04-405c-8862-64007f79f14c', 'experience-the-sound-and-light-show-of-philae-temple', 'Experience the Sound and Light Show of Philae Temple', (SELECT id FROM cities WHERE slug = 'aswan' LIMIT 1), 'Aswan', (SELECT id FROM trip_categories WHERE slug = 'spiritual' LIMIT 1), '1 day', 1440, 'Embark on a captivating journey through the rich ancient Egyptian civilization with this exceptional experience of the Sound and Light Show at Philae Temple, that will take you on a narrated journey to discover the legends of the ancient Egyptians. This nighttime performance brings this temple back to life, together with Egyptian Gods and Goddesses, like Isis and Osiris. The temple itself has a marvelous story, since early centuries, the site original site of Philae Temple was flooded for six months each year, so in the 60s an incredible restoration program started, and the Temple was moved stone by stone to the current location. Enjoy the spectacular lights of the multimedia presentations which vividly reveal the form and majesty of this ancient site and walk through the magnificent temple as its history gets narrated. After the show, the transfer will take you back to your hotel.', '/trips/experience-the-sound-and-light-show-of-philae-temple.png', 32, 'USD', NULL, 0, 0, 1, 47, 0, 'Economy', 'legacy', 1, '{"source":"legacyCatalog","sourceCities":["Aswan"],"sourceCategories":["Spiritual","Adventure Trips","Historical"]}') ON DUPLICATE KEY UPDATE title = VALUES(title), city_id = VALUES(city_id), location_label = VALUES(location_label), category_id = VALUES(category_id), duration_label = VALUES(duration_label), duration_minutes = VALUES(duration_minutes), description = VALUES(description), image_url = VALUES(image_url), price_from = VALUES(price_from), currency = VALUES(currency), rating = VALUES(rating), review_count = VALUES(review_count), is_featured = VALUES(is_featured), is_active = 1, solo_price = VALUES(solo_price), discount_percent = VALUES(discount_percent), price_level = VALUES(price_level), source_type = VALUES(source_type), catalog_visible = VALUES(catalog_visible), metadata = VALUES(metadata);
INSERT INTO trip_day_plans (trip_id, day_number, activities) VALUES ((SELECT id FROM trips WHERE slug = 'experience-the-sound-and-light-show-of-philae-temple' LIMIT 1), 1, '[{"time":"19:00","title":" Sound & Light Show   Experience the narrated journey through ancient Egyptian legends. The temple walls come alive with lights, colors, and storytelling about Isis, Osiris, and the history of Philae."},{"time":"06:00","title":"Hotel Pick‑up in Aswan   Meet your driver and transfer to the Nile dock"}]') ON DUPLICATE KEY UPDATE activities = VALUES(activities);
