INSERT INTO trips (id, slug, title, city_id, location_label, category_id, duration_label, duration_minutes, description, image_url, price_from, currency, rating, review_count, is_featured, is_active, solo_price, discount_percent, price_level, source_type, catalog_visible, metadata) VALUES ('837f8b3a-5de4-41a7-9dbc-6e8e41371b3b', 'discover-magawish-island-with-snorkeling-cruise-and-lunch-in-hurghada', 'Discover Magawish Island with snorkeling cruise and lunch in Hurghada', (SELECT id FROM cities WHERE slug = 'hurghada' LIMIT 1), 'Hurghada', (SELECT id FROM trip_categories WHERE slug = 'adventure-trips' LIMIT 1), '1 day', 1440, 'Embark on a memorable snorkeling adventure to Magawish Island, a hidden gem in the Red Sea. This full-day tour includes hotel pickup from Hurghada, Makadi, El Gouna, Sahl Hasheesh, or Soma Bay, a scenic boat cruise, multiple snorkeling stops, a buffet lunch on board, and leisure time on the island. Begin your journey with a convenient hotel pickup and transfer to the jetty, where your boat awaits. cruise along the stunning Hurghada Riviera, taking in panoramic views before arriving at your first snorkeling site. Dive into crystal-clear waters to explore vibrant coral reefs teeming with colorful marine life including parrotfish, angelfish, and clownfish. After your first snorkel, enjoy a delicious buffet lunch on the boat. After lunch, dock at Magawish Island and enjoy approximately 90 minutes of free time. Whether you choose to snorkel among coral heads in the clear lagoon, stroll along the sandy beach, or relax on the serene white shoreline, it''s your time to unwind and explore. Conclude your day with a relaxing cruise back to the jetty, followed by a comfortable transfer back to your hotel.', '/trips/discover-magawish-island-with-snorkeling-cruise-and-lunch-in-hurghada.png', 37, 'USD', NULL, 0, 0, 1, 52, 30, 'Economy', 'legacy', 1, '{"source":"legacyCatalog","sourceCities":["Hurghada"],"sourceCategories":["Adventure Trips","Family Friendly"]}') ON DUPLICATE KEY UPDATE title = VALUES(title), city_id = VALUES(city_id), location_label = VALUES(location_label), category_id = VALUES(category_id), duration_label = VALUES(duration_label), duration_minutes = VALUES(duration_minutes), description = VALUES(description), image_url = VALUES(image_url), price_from = VALUES(price_from), currency = VALUES(currency), rating = VALUES(rating), review_count = VALUES(review_count), is_featured = VALUES(is_featured), is_active = 1, solo_price = VALUES(solo_price), discount_percent = VALUES(discount_percent), price_level = VALUES(price_level), source_type = VALUES(source_type), catalog_visible = VALUES(catalog_visible), metadata = VALUES(metadata);
INSERT INTO trip_day_plans (trip_id, day_number, activities) VALUES ((SELECT id FROM trips WHERE slug = 'discover-magawish-island-with-snorkeling-cruise-and-lunch-in-hurghada' LIMIT 1), 1, '[{"time":"09:00","title":"Boat Departure   Cruise along the Red Sea Riviera, enjoying panoramic views."},{"time":"14:30","title":"Second Snorkeling Stop (Optional)   Explore another reef site before heading back."},{"time":"17:00","title":" Hotel Drop‑off   End of tour."}]') ON DUPLICATE KEY UPDATE activities = VALUES(activities);
INSERT INTO trip_inclusions (trip_id, item, sort_order) VALUES ((SELECT id FROM trips WHERE slug = 'discover-magawish-island-with-snorkeling-cruise-and-lunch-in-hurghada' LIMIT 1), 'Guided tour', 0) ON DUPLICATE KEY UPDATE sort_order = VALUES(sort_order);
