INSERT INTO trips (id, slug, title, city_id, location_label, category_id, duration_label, duration_minutes, description, image_url, price_from, currency, rating, review_count, is_featured, is_active, solo_price, discount_percent, price_level, source_type, catalog_visible, metadata) VALUES ('2e3b3427-0a1b-4ff2-b1aa-7958b101c21f', 'luxor-day-tour-by-flight-from-sharm-el-sheikh', 'Luxor day tour by flight from Sharm El Sheikh', (SELECT id FROM cities WHERE slug = 'sharm-el-sheikh' LIMIT 1), 'Sharm El Sheikh · Luxor', (SELECT id FROM trip_categories WHERE slug = 'historical' LIMIT 1), '1 day', 1440, 'Discover the eternal story of ancient Luxor as you check out its most loved treasures all in one day! Luxor is home to many iconic jewels like Karnak Temple with the Open-Air Museum, the Valley of the Kings and Hatshepsut Temple. Enjoy a complimentary pick-up in the early hours of the morning from your hotel in Sharm El Sheikh and drive to Sharm El Sheikh Airport for 1-hour flight to Luxor Airport, where Travco Representative will welcome you and introduce your Egyptologist who will be happy to share their love to history with you. Head straight to your first stop of the day, the Valley of the Kings. You''ll enter three of its 63 royal tombs and then take in the ancient Mortuary Temple of Hatshepsut and the staggering Colossi of Memnon, two monumental statues of equally monumental size! Then it''s time to rest your legs and tuck into a delicious set menu lunch before moving onto the impressive Karnak Temple, a sprawling complex of towering temples. Expect a jam-packed day of temples, tombs and monuments that sweep you through thousands of years of history. Flight back to Sharm El Sheikh and get transferred to your hotel.', '/trips/luxor-day-tour-by-flight-from-sharm-el-sheikh.png', 177, 'USD', NULL, 0, 0, 1, 247, 0, 'Standard', 'legacy', 1, '{"source":"legacyCatalog","sourceCities":["Sharm El Sheikh","Luxor"],"sourceCategories":["Historical","Family Friendly","One Day Trips","Spiritual","Luxury Tours"]}') ON DUPLICATE KEY UPDATE title = VALUES(title), city_id = VALUES(city_id), location_label = VALUES(location_label), category_id = VALUES(category_id), duration_label = VALUES(duration_label), duration_minutes = VALUES(duration_minutes), description = VALUES(description), image_url = VALUES(image_url), price_from = VALUES(price_from), currency = VALUES(currency), rating = VALUES(rating), review_count = VALUES(review_count), is_featured = VALUES(is_featured), is_active = 1, solo_price = VALUES(solo_price), discount_percent = VALUES(discount_percent), price_level = VALUES(price_level), source_type = VALUES(source_type), catalog_visible = VALUES(catalog_visible), metadata = VALUES(metadata);
