INSERT INTO trips (id, slug, title, city_id, location_label, category_id, duration_label, duration_minutes, description, image_url, price_from, currency, rating, review_count, is_featured, is_active, solo_price, discount_percent, price_level, source_type, catalog_visible, metadata) VALUES ('a26b82ef-f343-4da6-bb41-9378ba9f1599', 'super-4x4-safari-with-sand-buggies-camel-ride-in-marsa-alam', 'Super 4x4 safari with sand buggies & Camel ride in Marsa Alam', (SELECT id FROM cities WHERE slug = 'marsa-alam' LIMIT 1), 'Marsa Alam', (SELECT id FROM trip_categories WHERE slug = 'family-friendly' LIMIT 1), '1 day', 1440, 'Get ready for an unforgettable desert experience just outside Marsa Alam! Your adventure begins as you climb into a rugged 4x4 vehicle and head deep into Egypt’s dramatic Eastern Desert. After an exciting one-hour drive through striking mountain scenery, you’ll arrive at a traditional Bedouin camp. Here, you’ll have the unique opportunity to meet members of the local Bedouin community and learn about their way of life. Then, shift gears for high-octane fun as you hop into a dune buggy. Speed across the sand, navigating dusty tracks and dunes for a heart-pounding ride through the wild terrain. Next, slow things down with a peaceful camel ride across the desert sands — a timeless way to explore this breathtaking landscape. As the day winds down and the sun sets behind the mountains, sit back and enjoy a delicious dinner under the desert sky — the perfect end to an epic day of adventure.', '/trips/super-4x4-safari-with-sand-buggies-camel-ride-in-marsa-alam.png', 47, 'USD', NULL, 0, 0, 1, 67, 0, 'Economy', 'legacy', 1, '{"source":"legacyCatalog","sourceCities":["Marsa Alam"],"sourceCategories":["Family Friendly","One Day Trips"]}') ON DUPLICATE KEY UPDATE title = VALUES(title), city_id = VALUES(city_id), location_label = VALUES(location_label), category_id = VALUES(category_id), duration_label = VALUES(duration_label), duration_minutes = VALUES(duration_minutes), description = VALUES(description), image_url = VALUES(image_url), price_from = VALUES(price_from), currency = VALUES(currency), rating = VALUES(rating), review_count = VALUES(review_count), is_featured = VALUES(is_featured), is_active = 1, solo_price = VALUES(solo_price), discount_percent = VALUES(discount_percent), price_level = VALUES(price_level), source_type = VALUES(source_type), catalog_visible = VALUES(catalog_visible), metadata = VALUES(metadata);
INSERT INTO trip_day_plans (trip_id, day_number, activities) VALUES ((SELECT id FROM trips WHERE slug = 'super-4x4-safari-with-sand-buggies-camel-ride-in-marsa-alam' LIMIT 1), 1, '[{"time":"14:30","title":" Hotel Pick‑up in Marsa Alam   Transfer by air‑conditioned vehicle to the desert camp."}]') ON DUPLICATE KEY UPDATE activities = VALUES(activities);
