INSERT INTO trips (id, slug, title, city_id, location_label, category_id, duration_label, duration_minutes, description, image_url, price_from, currency, rating, review_count, is_featured, is_active, solo_price, discount_percent, price_level, source_type, catalog_visible, metadata) VALUES ('07a9c24a-0fba-4725-80b3-96a0d4bce91e', 'tour-of-karnak-and-luxor-temples-with-the-sphinx-alley-from-luxor', 'Tour of Karnak and Luxor Temples with the Sphinx Alley from Luxor', (SELECT id FROM cities WHERE slug = 'luxor' LIMIT 1), 'Luxor', (SELECT id FROM trip_categories WHERE slug = 'spiritual' LIMIT 1), '1 day', 1440, 'Be picked up from your accommodation either in a hotel or a Nile Cruise as you''ll travel to the Jewel of the Egyptian Temples, Karnak. You''ll then understand with your own eyes why, as Amelia Edwards wrote, "This is a place that has been much written about and often painted, but of which no writing and no art can convey more than a dwarfed and pallid impression”. Explore its spectacular complex of sanctuaries, kiosks, pylons, and obelisks, all dedicated to the Theban gods and Egypt''s Middle and New Kingdom rulers. Next, experience the Kebash path, also known as Sphinx Alley, and learn how it was built to connect the vast Karnak temple to the Luxor Temple. Plus, you''ll discover that the Ancient Egyptians walked along the path once a year with the statues of Amun, the central god, and his wife Mut in a symbolic re-enactment of the deities'' marriage. The road was later used by the Romans and is believed to have been renovated by the Ptolemaic Queen Cleopatra, who left her "cartouche" which is an inscribed hieroglyphic. The tour also includes a visit to the fantastic Luxor Temple.', '/trips/tour-of-karnak-and-luxor-temples-with-the-sphinx-alley-from-luxor.png', 45, 'USD', NULL, 0, 0, 1, 67, 30, 'Economy', 'legacy', 1, '{"source":"legacyCatalog","sourceCities":["Luxor"],"sourceCategories":["Spiritual","One Day Trips","Family Friendly","Historical","Adventure Trips"]}') ON DUPLICATE KEY UPDATE title = VALUES(title), city_id = VALUES(city_id), location_label = VALUES(location_label), category_id = VALUES(category_id), duration_label = VALUES(duration_label), duration_minutes = VALUES(duration_minutes), description = VALUES(description), image_url = VALUES(image_url), price_from = VALUES(price_from), currency = VALUES(currency), rating = VALUES(rating), review_count = VALUES(review_count), is_featured = VALUES(is_featured), is_active = 1, solo_price = VALUES(solo_price), discount_percent = VALUES(discount_percent), price_level = VALUES(price_level), source_type = VALUES(source_type), catalog_visible = VALUES(catalog_visible), metadata = VALUES(metadata);
INSERT INTO trip_day_plans (trip_id, day_number, activities) VALUES ((SELECT id FROM trips WHERE slug = 'tour-of-karnak-and-luxor-temples-with-the-sphinx-alley-from-luxor' LIMIT 1), 1, '[{"time":"08:00","title":" Hotel/Nile Cruise Pick‑up   Meet your Egyptologist guide and transfer to Luxor East Bank."},{"time":"08:30","title":" Guided visit to Karnak Temple Complex. Explore sanctuaries, pylons, obelisks, and learn why Amelia Edwards described it as beyond words or art."},{"time":"08:30","title":" Guided visit to Karnak Temple Complex. Explore sanctuaries, pylons, obelisks, and learn why Amelia Edwards described it as beyond words or art."},{"time":"11:45","title":" Luxor Temple   Admire the temple on the Nile Corniche, with its grand colonnades and statues of Ramses II."},{"time":"08:00","title":" Hotel/Nile Cruise Pick‑up   Meet your Egyptologist guide and transfer to Luxor East Bank."},{"time":"10:45","title":" Sphinx Alley (Kabash Path)   Walk along the restored avenue connecting Karnak to Luxor Temple. Learn about the annual Opet Festival, when statues of Amun and Mut were carried along the path. Discover Roman and Ptolemaic influences, including Cleopatra’s cartouche."},{"time":"13:00","title":" Return to Hotel/Nile Cruise   End of tour."},{"time":"10:45","title":" Sphinx Alley (Kabash Path)   Walk along the restored avenue connecting Karnak to Luxor Temple. Learn about the annual Opet Festival, when statues of Amun and Mut were carried along the path. Discover Roman and Ptolemaic influences, including Cleopatra’s cartouche."},{"time":"08:00","title":" Hotel/Nile Cruise Pick‑up   Meet your Egyptologist guide and transfer to Luxor East Bank."},{"time":"08:30","title":" Guided visit to Karnak Temple Complex. Explore sanctuaries, pylons, obelisks, and learn why Amelia Edwards described it as beyond words or art."},{"time":"08:30","title":" Guided visit to Karnak Temple Complex. Explore sanctuaries, pylons, obelisks, and learn why Amelia Edwards described it as beyond words or art."},{"time":"11:45","title":" Luxor Temple   Admire the temple on the Nile Corniche, with its grand colonnades and statues of Ramses II."},{"time":"11:45","title":" Luxor Temple   Admire the temple on the Nile Corniche, with its grand colonnades and statues of Ramses II."},{"time":"08:00","title":" Hotel/Nile Cruise Pick‑up   Meet your Egyptologist guide and transfer to Luxor East Bank."},{"time":"13:00","title":" Return to Hotel/Nile Cruise   End of tour."},{"time":"13:00","title":" Return to Hotel/Nile Cruise   End of tour."}]') ON DUPLICATE KEY UPDATE activities = VALUES(activities);
INSERT INTO trips (id, slug, title, city_id, location_label, category_id, duration_label, duration_minutes, description, image_url, price_from, currency, rating, review_count, is_featured, is_active, solo_price, discount_percent, price_level, source_type, catalog_visible, metadata) VALUES ('716fdb81-c055-4d1e-a9c4-99520afc3994', 'tour-of-civilization-museum-and-salah-el-din-citadel-with-el-khan-bazaar-from-ca', 'Tour of Civilization Museum and Salah El Din Citadel with El Khan Bazaar from Cairo', (SELECT id FROM cities WHERE slug = 'cairo' LIMIT 1), 'Cairo', (SELECT id FROM trip_categories WHERE slug = 'historical' LIMIT 1), '1 day', 1440, 'Enjoy a complimentary pick-up from your hotel in Cairo, Giza or 6th October City and head directly to a cultural and historical journey that will leave you mesmerized, where your Egyptologist will be happy to share their love to history with you. From exploring a museum with 50,000 artifacts of Egyptian civilization to the Mokattam Hills of Old Cairo and into a world of crafts at the bazaar. You''ll hear how the National Museum of Egyptian Civilization was officially opened by the Egyptian president, right before 22 mummies, including 18 kings and four queens, were moved from the Egyptian Museum in an event termed the Pharaohs'' Golden Parade. Marvel at the 50,000 artifacts of Egyptian civilization from prehistoric times to the present day as you explore the museum. Next, discover the Citadel situated on a highly visible spur of the Mokattam Hills of Old Cairo. You''ll learn about it being the nerve center of Egypt for almost 700 years and a grand structure that began in 1176. Lastly, visit the popular bazaar district home to many Egyptian artisans involved in the production of traditional crafts and souvenirs to end your day.', '/trips/tour-of-civilization-museum-and-salah-el-din-citadel-with-el-khan-bazaar-from-ca.png', 57, 'USD', NULL, 0, 0, 1, 87, 0, 'Economy', 'legacy', 1, '{"source":"legacyCatalog","sourceCities":["Cairo"],"sourceCategories":["Historical","Adventure Trips"]}') ON DUPLICATE KEY UPDATE title = VALUES(title), city_id = VALUES(city_id), location_label = VALUES(location_label), category_id = VALUES(category_id), duration_label = VALUES(duration_label), duration_minutes = VALUES(duration_minutes), description = VALUES(description), image_url = VALUES(image_url), price_from = VALUES(price_from), currency = VALUES(currency), rating = VALUES(rating), review_count = VALUES(review_count), is_featured = VALUES(is_featured), is_active = 1, solo_price = VALUES(solo_price), discount_percent = VALUES(discount_percent), price_level = VALUES(price_level), source_type = VALUES(source_type), catalog_visible = VALUES(catalog_visible), metadata = VALUES(metadata);
