INSERT INTO trip_inclusions (trip_id, item, sort_order) VALUES ((SELECT id FROM trips WHERE slug = 'tour-of-civilization-museum-and-salah-el-din-citadel-with-el-khan-bazaar-from-ca' LIMIT 1), 'Hotel pick-up and drop-off', 1) ON DUPLICATE KEY UPDATE sort_order = VALUES(sort_order);
INSERT INTO trips (id, slug, title, city_id, location_label, category_id, duration_label, duration_minutes, description, image_url, price_from, currency, rating, review_count, is_featured, is_active, solo_price, discount_percent, price_level, source_type, catalog_visible, metadata) VALUES ('4396d686-5fb3-41c8-a6eb-a0dabee3009c', 'hot-air-balloon-experience-from-luxor-hotels-and-nile-cruises', 'Hot Air Balloon Experience from Luxor Hotels and Nile Cruises', (SELECT id FROM cities WHERE slug = 'luxor' LIMIT 1), 'Luxor', (SELECT id FROM trip_categories WHERE slug = 'family-friendly' LIMIT 1), '1 day', 1440, 'Have you ever been in a hot air balloon before? If not, then, it is time to experience one of the top seven hot air ballooning destinations published by Matador Network. This is a trip that looks like it’s fresh out of a Disney movie. A magical and breathtaking experience as you fly over the world’s largest open-air museum aboard a colorful hot air balloon. The tour starts by an early pick-up from your hotel , followed by a short transfer to the Balloon take –off place. Ride on the Balloon and enjoy a unique experience in your lifetime. The proximity low flight gives you the chance to enjoy the splendor of the ancient historical sights of Luxor from the air. See this spectacular landscape from the unique viewpoint that only hot air ballooning can provide as you glide majestically above the burial grounds of the great Pharaohs. The balloons are checked daily by accredited engineers and trainers to ensure your safety.', '/trips/hot-air-balloon-experience-from-luxor-hotels-and-nile-cruises.png', 64, 'USD', NULL, 0, 0, 1, 87, 10, 'Economy', 'legacy', 1, '{"source":"legacyCatalog","sourceCities":["Luxor"],"sourceCategories":["Family Friendly","Historical","Adventure Trips","One Day Trips"]}') ON DUPLICATE KEY UPDATE title = VALUES(title), city_id = VALUES(city_id), location_label = VALUES(location_label), category_id = VALUES(category_id), duration_label = VALUES(duration_label), duration_minutes = VALUES(duration_minutes), description = VALUES(description), image_url = VALUES(image_url), price_from = VALUES(price_from), currency = VALUES(currency), rating = VALUES(rating), review_count = VALUES(review_count), is_featured = VALUES(is_featured), is_active = 1, solo_price = VALUES(solo_price), discount_percent = VALUES(discount_percent), price_level = VALUES(price_level), source_type = VALUES(source_type), catalog_visible = VALUES(catalog_visible), metadata = VALUES(metadata);
INSERT INTO trip_day_plans (trip_id, day_number, activities) VALUES ((SELECT id FROM trips WHERE slug = 'hot-air-balloon-experience-from-luxor-hotels-and-nile-cruises' LIMIT 1), 1, '[{"time":"06:45","title":"Landing & Celebration   Receive a flight certificate and enjoy light refreshments"},{"time":"07:30","title":"Return Transfer   Drop‑off at your hotel or Nile cruise."}]') ON DUPLICATE KEY UPDATE activities = VALUES(activities);
INSERT INTO trip_inclusions (trip_id, item, sort_order) VALUES ((SELECT id FROM trips WHERE slug = 'hot-air-balloon-experience-from-luxor-hotels-and-nile-cruises' LIMIT 1), 'Hotel pick-up and drop-off', 0) ON DUPLICATE KEY UPDATE sort_order = VALUES(sort_order);
INSERT INTO trips (id, slug, title, city_id, location_label, category_id, duration_label, duration_minutes, description, image_url, price_from, currency, rating, review_count, is_featured, is_active, solo_price, discount_percent, price_level, source_type, catalog_visible, metadata) VALUES ('131e4a4b-572d-48a8-9bf2-b242b553e53f', 'tour-of-the-grand-museum-and-giza-pyramids-with-lunch-from-cairo', 'Tour of the Grand Museum and Giza Pyramids with lunch from Cairo', (SELECT id FROM cities WHERE slug = 'cairo' LIMIT 1), 'Cairo', (SELECT id FROM trip_categories WHERE slug = 'family-friendly' LIMIT 1), '1 day', 1440, 'Be one of the first visitors to experience the New Grand Egyptian Museum (GEM) set to be the world''s largest archaeological museum dedicated to a single civilization. It houses over 100,000 artefacts from ancient Egypt. It is designed to provide a modern context for historic artefacts, featuring permanent and temporary exhibition spaces, a children''s museum, conference facilities, and extensive gardens. Your experience will be completed by visiting the Giza Pyramids, the world''s most iconic and ancient structures. You''ll be picked up from your accommodation in Cairo from where you''ll be driven to the Giza Pyramids. Admire the last remaining wonder of the ancient world before standing in awe beneath the Great Sphinx. Next, you''ll enjoy a delicious lunch at a local restaurant. Entering the Grand Egyptian Museum, you''ll then start the journey of the Egyptian kings to eternity. Ascend the Grand Staircase, surrounded by a precisely curated collection of 64 monumental treasures from the most illustrious past, and let the mysteries of ancient Egypt unveil before your eyes. Then enter the fascinating Hall of Tutankhamun Treasures, home to the most extensive collection ever displayed from the young king’s tomb. Its immersive showcases reveal the craftsmanship, rituals, and royal splendour of the 18th Dynasty. Each work of art remains a piece of the intricate puzzle that once was ancient Egypt’s fascinating civilization. Prepare yourself to discover Egypt''s most prized possessions.', '/trips/tour-of-the-grand-museum-and-giza-pyramids-with-lunch-from-cairo.png', 86, 'USD', NULL, 0, 0, 1, 117, 0, 'Standard', 'legacy', 1, '{"source":"legacyCatalog","sourceCities":["Cairo"],"sourceCategories":["Family Friendly","Adventure Trips","One Day Trips","Historical"]}') ON DUPLICATE KEY UPDATE title = VALUES(title), city_id = VALUES(city_id), location_label = VALUES(location_label), category_id = VALUES(category_id), duration_label = VALUES(duration_label), duration_minutes = VALUES(duration_minutes), description = VALUES(description), image_url = VALUES(image_url), price_from = VALUES(price_from), currency = VALUES(currency), rating = VALUES(rating), review_count = VALUES(review_count), is_featured = VALUES(is_featured), is_active = 1, solo_price = VALUES(solo_price), discount_percent = VALUES(discount_percent), price_level = VALUES(price_level), source_type = VALUES(source_type), catalog_visible = VALUES(catalog_visible), metadata = VALUES(metadata);
INSERT INTO trip_day_plans (trip_id, day_number, activities) VALUES ((SELECT id FROM trips WHERE slug = 'tour-of-the-grand-museum-and-giza-pyramids-with-lunch-from-cairo' LIMIT 1), 1, '[{"time":"07:30","title":" Hotel Pick‑up   Meet your Egyptologist guide and driver at your Cairo hotel. Begin the drive to Giza."},{"time":"08:00","title":" Giza Pyramids & Sphinx   Explore the Great Pyramid of Khufu, Pyramid of Khafre, and Pyramid of Menkaure. Stand in awe before the Great Sphinx, the guardian of the plateau."}]') ON DUPLICATE KEY UPDATE activities = VALUES(activities);
INSERT INTO trip_inclusions (trip_id, item, sort_order) VALUES ((SELECT id FROM trips WHERE slug = 'tour-of-the-grand-museum-and-giza-pyramids-with-lunch-from-cairo' LIMIT 1), 'Hotel pick-up and drop-off', 0) ON DUPLICATE KEY UPDATE sort_order = VALUES(sort_order);
