INSERT INTO trips (id, slug, title, city_id, location_label, category_id, duration_label, duration_minutes, description, image_url, price_from, currency, rating, review_count, is_featured, is_active, solo_price, discount_percent, price_level, source_type, catalog_visible, metadata) VALUES ('8601c884-3c35-469f-a2b7-b8bb897b90fe', '5-days-4-nights-nile-cruise-from-luxor-to-aswan', '5 Days / 4 Nights Nile Cruise from Luxor to Aswan', (SELECT id FROM cities WHERE slug = 'aswan' LIMIT 1), 'Aswan · Luxor', (SELECT id FROM trip_categories WHERE slug = 'historical' LIMIT 1), '5 days', 7200, 'Sail the Nile in style from Luxor to Aswan aboard a 5★ cruise for 5 days and 4 nights. Visit iconic temples, tombs, and historical landmarks with a private Egyptologist, all while enjoying full-board luxury and breathtaking views.', '/trips/5-days-4-nights-nile-cruise-from-luxor-to-aswan.png', 397, 'USD', NULL, 0, 0, 1, 547, 0, 'Luxury', 'legacy', 1, '{"source":"legacyCatalog","sourceCities":["Aswan","Luxor"],"sourceCategories":["Historical","Nile Cruises","Family Friendly","Spiritual"]}') ON DUPLICATE KEY UPDATE title = VALUES(title), city_id = VALUES(city_id), location_label = VALUES(location_label), category_id = VALUES(category_id), duration_label = VALUES(duration_label), duration_minutes = VALUES(duration_minutes), description = VALUES(description), image_url = VALUES(image_url), price_from = VALUES(price_from), currency = VALUES(currency), rating = VALUES(rating), review_count = VALUES(review_count), is_featured = VALUES(is_featured), is_active = 1, solo_price = VALUES(solo_price), discount_percent = VALUES(discount_percent), price_level = VALUES(price_level), source_type = VALUES(source_type), catalog_visible = VALUES(catalog_visible), metadata = VALUES(metadata);
