INSERT INTO trips (id, slug, title, city_id, location_label, category_id, duration_label, duration_minutes, description, image_url, price_from, currency, rating, review_count, is_featured, is_active, solo_price, discount_percent, price_level, source_type, catalog_visible, metadata) VALUES ('afd190b1-192d-4b21-aa46-d19bbde7cbe0', 'valley-of-the-kings-and-hatshepsut-temple-with-felucca-experience-from-luxor', 'Valley of the Kings and Hatshepsut Temple with Felucca experience from Luxor', (SELECT id FROM cities WHERE slug = 'luxor' LIMIT 1), 'Luxor', (SELECT id FROM trip_categories WHERE slug = 'one-day-trips' LIMIT 1), '1 day', 1440, 'Discover the Valley of the Kings, Hatshepsut Temple, and the Nile onboard a traditional Egyptian wooden boat on this half-day tour with your Egyptologist. Be picked up from your hotel as you''ll drive to Luxor West Bank to see the Valley of the Kings. You''ll learn why it was once called the “Gates of the Kings” or the “Place of Truth” and the mighty kings who once lay there in stone sarcophagus, awaiting immortality, including Tutankhamun. Then, you''ll explore the temple of Hatshepsut, rising out of the desert and hear how, in 1876, the greatest mummy find in history was made. Next, before crossing the River Nile to Luxor East Bank, you’ll stop off at two 60-foot stone statues that have stood for more than 3,000 years. You''ll then relax onboard the felucca for an hour sailing along the Nile, observing Luxor City', '/trips/valley-of-the-kings-and-hatshepsut-temple-with-felucca-experience-from-luxor.png', 47, 'USD', NULL, 0, 0, 1, 67, 10, 'Economy', 'legacy', 1, '{"source":"legacyCatalog","sourceCities":["Luxor"],"sourceCategories":["One Day Trips","Adventure Trips","Spiritual","Family Friendly","Historical"]}') ON DUPLICATE KEY UPDATE title = VALUES(title), city_id = VALUES(city_id), location_label = VALUES(location_label), category_id = VALUES(category_id), duration_label = VALUES(duration_label), duration_minutes = VALUES(duration_minutes), description = VALUES(description), image_url = VALUES(image_url), price_from = VALUES(price_from), currency = VALUES(currency), rating = VALUES(rating), review_count = VALUES(review_count), is_featured = VALUES(is_featured), is_active = 1, solo_price = VALUES(solo_price), discount_percent = VALUES(discount_percent), price_level = VALUES(price_level), source_type = VALUES(source_type), catalog_visible = VALUES(catalog_visible), metadata = VALUES(metadata);
