INSERT INTO trip_inclusions (trip_id, item, sort_order) VALUES ((SELECT id FROM trips WHERE slug = 'valley-of-the-kings-and-hatshepsut-temple-with-felucca-experience-from-luxor' LIMIT 1), 'Nile Felucca tour with water and soft drinks onboard the Felucca', 0) ON DUPLICATE KEY UPDATE sort_order = VALUES(sort_order);
INSERT INTO trip_inclusions (trip_id, item, sort_order) VALUES ((SELECT id FROM trips WHERE slug = 'valley-of-the-kings-and-hatshepsut-temple-with-felucca-experience-from-luxor' LIMIT 1), 'Insurance', 1) ON DUPLICATE KEY UPDATE sort_order = VALUES(sort_order);
INSERT INTO trips (id, slug, title, city_id, location_label, category_id, duration_label, duration_minutes, description, image_url, price_from, currency, rating, review_count, is_featured, is_active, solo_price, discount_percent, price_level, source_type, catalog_visible, metadata) VALUES ('f25b340a-1edf-4667-a8cc-da215ff9c309', 'full-day-tour-of-luxor-highlights-from-luxor-hotels-and-nile-cruises', 'Full day tour of Luxor Highlights from Luxor hotels and Nile Cruises', (SELECT id FROM cities WHERE slug = 'luxor' LIMIT 1), 'Luxor', (SELECT id FROM trip_categories WHERE slug = 'historical' LIMIT 1), '1 day', 1440, 'Discover the historical treasures of Luxor on this full day guided tour and learn its history through its top sites (and hidden ones too): Valley of the Kings, Karnak Temple, Sphinx Avenue and many more. Your tour starts with a pick-up from your hotel lobby, then head directly to the Valley of the Kings as you hear why it was once called the “Gates of the Kings” or the “Place of Truth”. You''ll also marvel at Hatshepsut Temple rising out of the desert plain in a series of terraces and learn about the greatest mummy find in history in 1876. Then, before crossing the River Nile to Luxor East Bank, you’ll pause to admire two 60-foot stone statues named The Colossi of Memnon that have stood for more than 3,000 years. Next, you''ll cross the tranquil waters of the River Nile by motorboat to the Luxor East Bank, where it''s time to for a tasty lunch. You''ll lastly explore the Jewel of the Egyptian Temples, Karnak, with its complex of sanctuaries, kiosks, pylons and obelisks. Unforgettable experience!', '/trips/full-day-tour-of-luxor-highlights-from-luxor-hotels-and-nile-cruises.png', 62, 'USD', NULL, 0, 0, 1, 87, 20, 'Standard', 'legacy', 1, '{"source":"legacyCatalog","sourceCities":["Luxor"],"sourceCategories":["Historical","Adventure Trips","Family Friendly"]}') ON DUPLICATE KEY UPDATE title = VALUES(title), city_id = VALUES(city_id), location_label = VALUES(location_label), category_id = VALUES(category_id), duration_label = VALUES(duration_label), duration_minutes = VALUES(duration_minutes), description = VALUES(description), image_url = VALUES(image_url), price_from = VALUES(price_from), currency = VALUES(currency), rating = VALUES(rating), review_count = VALUES(review_count), is_featured = VALUES(is_featured), is_active = 1, solo_price = VALUES(solo_price), discount_percent = VALUES(discount_percent), price_level = VALUES(price_level), source_type = VALUES(source_type), catalog_visible = VALUES(catalog_visible), metadata = VALUES(metadata);
