INSERT INTO trip_inclusions (trip_id, item, sort_order) VALUES ((SELECT id FROM trips WHERE slug = 'full-day-tour-of-luxor-highlights-from-luxor-hotels-and-nile-cruises' LIMIT 1), 'Transportation in air-conditioned vehicle.', 3) ON DUPLICATE KEY UPDATE sort_order = VALUES(sort_order);
INSERT INTO trips (id, slug, title, city_id, location_label, category_id, duration_label, duration_minutes, description, image_url, price_from, currency, rating, review_count, is_featured, is_active, solo_price, discount_percent, price_level, source_type, catalog_visible, metadata) VALUES ('6a3c332b-1ffb-46a3-9995-dfb8feb48a7d', 'discover-luxor-from-marsa-alam', 'Discover Luxor from Marsa Alam', (SELECT id FROM cities WHERE slug = 'marsa-alam' LIMIT 1), 'Marsa Alam · Luxor', (SELECT id FROM trip_categories WHERE slug = 'one-day-trips' LIMIT 1), '1 day', 1440, 'Discover one of the world''s greatest open-air museums including Karnak Temple and the Valley of the Kings plus the fascinating temple of Queen Hatshepsut. Get picked up in the early morning from your accommodation in Marsa Alam and Surroundings and set off to Luxor, where you will be taken directly to the West Bank of Thebes. Starting with the staggering Colossi of Memnon where you can see two massive stone statues of the Pharaoh Amenhotep III. Next, you will head to the Valley of the Kings, where the Tombs of the Great Egyptian Pharaohs such as Seti, Ramses, and the most famous Tut Ankh Amun. You’ll get to enter three of its 63 royal tombs. Resume driving to the amazing Temple of the famous Queen Hatshepsut. Then, you will cross the immortal Nile River to the East Bank, where you can try local delicacies for lunch. Finally, you will end your tour with a visit to the Greatest Temple in Egypt and the World, the Complex of Karnak Temples. Resume driving back to your accommodation in Marsa Alam with unforgettable memories', '/trips/discover-luxor-from-marsa-alam.png', 87, 'USD', NULL, 0, 0, 1, 117, 30, 'Economy', 'legacy', 1, '{"source":"legacyCatalog","sourceCities":["Marsa Alam","Luxor"],"sourceCategories":["One Day Trips","Adventure Trips"]}') ON DUPLICATE KEY UPDATE title = VALUES(title), city_id = VALUES(city_id), location_label = VALUES(location_label), category_id = VALUES(category_id), duration_label = VALUES(duration_label), duration_minutes = VALUES(duration_minutes), description = VALUES(description), image_url = VALUES(image_url), price_from = VALUES(price_from), currency = VALUES(currency), rating = VALUES(rating), review_count = VALUES(review_count), is_featured = VALUES(is_featured), is_active = 1, solo_price = VALUES(solo_price), discount_percent = VALUES(discount_percent), price_level = VALUES(price_level), source_type = VALUES(source_type), catalog_visible = VALUES(catalog_visible), metadata = VALUES(metadata);
