INSERT INTO trips (id, slug, title, city_id, location_label, category_id, duration_label, duration_minutes, description, image_url, price_from, currency, rating, review_count, is_featured, is_active, solo_price, discount_percent, price_level, source_type, catalog_visible, metadata) VALUES ('cd265f65-db3f-4020-830a-e11972f1dca8', 'one-day-alexandria-trip-from-cairo', 'One-Day Alexandria Trip from Cairo', (SELECT id FROM cities WHERE slug = 'alexandria' LIMIT 1), 'Alexandria · Cairo', (SELECT id FROM trip_categories WHERE slug = 'family-friendly' LIMIT 1), '1 day', 1440, 'Explore the city where history and the Mediterranean meet—Alexandria, the Bride of the Sea. Begin with a morning pickup from Cairo and journey to this coastal gem, known for its Greco-Roman heritage and modern charm. Discover the mysteries of the Kom el-Shoqafa Catacombs, marvel at Pompey’s Pillar, and enjoy a delicious seafood lunch. Continue to the majestic Qaitbay Citadel, built on the ruins of the Lighthouse of Alexandria, and walk the paths of history by the sea. Optional visit to the New Alexandria Library is available if time allows.', '/trips/one-day-alexandria-trip-from-cairo.png', 79, 'USD', NULL, 0, 0, 1, 117, 0, 'Economy', 'legacy', 1, '{"source":"legacyCatalog","sourceCities":["Alexandria","Cairo"],"sourceCategories":["Family Friendly"]}') ON DUPLICATE KEY UPDATE title = VALUES(title), city_id = VALUES(city_id), location_label = VALUES(location_label), category_id = VALUES(category_id), duration_label = VALUES(duration_label), duration_minutes = VALUES(duration_minutes), description = VALUES(description), image_url = VALUES(image_url), price_from = VALUES(price_from), currency = VALUES(currency), rating = VALUES(rating), review_count = VALUES(review_count), is_featured = VALUES(is_featured), is_active = 1, solo_price = VALUES(solo_price), discount_percent = VALUES(discount_percent), price_level = VALUES(price_level), source_type = VALUES(source_type), catalog_visible = VALUES(catalog_visible), metadata = VALUES(metadata);
INSERT INTO trip_day_plans (trip_id, day_number, activities) VALUES ((SELECT id FROM trips WHERE slug = 'one-day-alexandria-trip-from-cairo' LIMIT 1), 1, '[{"time":"12:00","title":"Enjoy a delicious seafood lunch at a local restaurant"},{"time":"13:30","title":" Qaitbay Citadel   Visit the fortress built on the site of the ancient Lighthouse of Alexandria."},{"time":"19:30","title":"Hotel Drop‑off in Cairo   End of tour."}]') ON DUPLICATE KEY UPDATE activities = VALUES(activities);
INSERT INTO trip_inclusions (trip_id, item, sort_order) VALUES ((SELECT id FROM trips WHERE slug = 'one-day-alexandria-trip-from-cairo' LIMIT 1), 'Transportation by modern A/C vehicle', 0) ON DUPLICATE KEY UPDATE sort_order = VALUES(sort_order);
INSERT INTO trip_inclusions (trip_id, item, sort_order) VALUES ((SELECT id FROM trips WHERE slug = 'one-day-alexandria-trip-from-cairo' LIMIT 1), 'Pickup and drop-off at Cairo/Giza hotels', 1) ON DUPLICATE KEY UPDATE sort_order = VALUES(sort_order);
INSERT INTO trips (id, slug, title, city_id, location_label, category_id, duration_label, duration_minutes, description, image_url, price_from, currency, rating, review_count, is_featured, is_active, solo_price, discount_percent, price_level, source_type, catalog_visible, metadata) VALUES ('26357c6e-69d2-4275-aac2-e172b49172d5', 'tour-of-the-high-dam-unfinished-obelisk-and-philae-temple-with-felucca-cruise', 'Tour of The High Dam, Unfinished Obelisk and Philae Temple with felucca cruise', (SELECT id FROM cities WHERE slug = 'aswan' LIMIT 1), 'Aswan', (SELECT id FROM trip_categories WHERE slug = 'family-friendly' LIMIT 1), '1 day', 1440, 'Discover the history, culture, and the amazing treasures gifted by the ancient and modern Egyptians to humanity and enjoy a sailing tour on a traditional felucca. After getting picked up from your hotel and head to Aswan High Dam, an engineering miracle built in 1960 to protect Egypt from the Nile annual floods, that generates constant electricity, and that has also formed Lake Nasser, the world’s largest artificial lake. The next stop will be the Unfinished Obelisk, a treasure that shows the techniques used by the ancient Egyptians to cut such vast pieces of obelisks from granite quarries; the Unfinished Obelisk would have been the largest single piece of stone ever handed if a flaw had not appeared in the granite. The last stop before embarking on the Felucca will be Philae Temple, which is the icon of Aswan. Get on board on the traditional canvas-sailed boats of the Nile, and admire the picturesque view of Aswan, the felucca’s captain will offer you bottled water and authentic tea, made freshly on the boat.', '/trips/tour-of-the-high-dam-unfinished-obelisk-and-philae-temple-with-felucca-cruise.png', 52, 'USD', NULL, 0, 0, 1, 72, 20, 'Economy', 'legacy', 1, '{"source":"legacyCatalog","sourceCities":["Aswan"],"sourceCategories":["Family Friendly","Spiritual","Adventure Trips","One Day Trips","Historical"]}') ON DUPLICATE KEY UPDATE title = VALUES(title), city_id = VALUES(city_id), location_label = VALUES(location_label), category_id = VALUES(category_id), duration_label = VALUES(duration_label), duration_minutes = VALUES(duration_minutes), description = VALUES(description), image_url = VALUES(image_url), price_from = VALUES(price_from), currency = VALUES(currency), rating = VALUES(rating), review_count = VALUES(review_count), is_featured = VALUES(is_featured), is_active = 1, solo_price = VALUES(solo_price), discount_percent = VALUES(discount_percent), price_level = VALUES(price_level), source_type = VALUES(source_type), catalog_visible = VALUES(catalog_visible), metadata = VALUES(metadata);
