INSERT INTO trips (id, slug, title, city_id, location_label, category_id, duration_label, duration_minutes, description, image_url, price_from, currency, rating, review_count, is_featured, is_active, solo_price, discount_percent, price_level, source_type, catalog_visible, metadata) VALUES ('48d12df4-a787-4a64-aa65-eecb27a74a07', 'experience-the-sound-and-light-show-of-the-karnak-temple-from-luxor', 'Experience the Sound and light show of the Karnak Temple from Luxor', (SELECT id FROM cities WHERE slug = 'luxor' LIMIT 1), 'Luxor', (SELECT id FROM trip_categories WHERE slug = 'adventure-trips' LIMIT 1), '1 day', 1440, 'Discover the sound and light show at the Karnak Temple on the three-hour guided tour and learn its history through intriguing storytelling which will light up your senses. After a complimentary pickup from the lobby of your hotel or Nile Cruise, you will travel to the avenue of Sphinxes, you''ll experience the atmosphere change as the show starts. Marvel as you pass through the first pylon to the Great Court and onto the Great Hypostyle Hall. Then, at the grandstand of the Sacred Lake is the show’s finale. You''ll also learn the history of Thebes and the lives of the many pharaohs who built sanctuaries, courts, statues, and obelisks in honor of Amun. Don’t miss this unique experience!', '/trips/experience-the-sound-and-light-show-of-the-karnak-temple-from-luxor.png', 32, 'USD', NULL, 0, 0, 1, 47, 20, 'Economy', 'legacy', 1, '{"source":"legacyCatalog","sourceCities":["Luxor"],"sourceCategories":["Adventure Trips"]}') ON DUPLICATE KEY UPDATE title = VALUES(title), city_id = VALUES(city_id), location_label = VALUES(location_label), category_id = VALUES(category_id), duration_label = VALUES(duration_label), duration_minutes = VALUES(duration_minutes), description = VALUES(description), image_url = VALUES(image_url), price_from = VALUES(price_from), currency = VALUES(currency), rating = VALUES(rating), review_count = VALUES(review_count), is_featured = VALUES(is_featured), is_active = 1, solo_price = VALUES(solo_price), discount_percent = VALUES(discount_percent), price_level = VALUES(price_level), source_type = VALUES(source_type), catalog_visible = VALUES(catalog_visible), metadata = VALUES(metadata);
