INSERT INTO trips (id, slug, title, city_id, location_label, category_id, duration_label, duration_minutes, description, image_url, price_from, currency, rating, review_count, is_featured, is_active, solo_price, discount_percent, price_level, source_type, catalog_visible, metadata) VALUES ('c2341501-963d-4a33-accc-f7e031a2636f', 'ultimate-desert-experience-quad-biking-camel-ride-bedouin-dinner-and-show', 'Ultimate Desert Experience: Quad Biking, Camel Ride, Bedouin Dinner and Show', (SELECT id FROM cities WHERE slug = 'sharm-el-sheikh' LIMIT 1), 'Sharm El Sheikh', (SELECT id FROM trip_categories WHERE slug = 'adventure-trips' LIMIT 1), '1 day', 1440, 'Embark on an unforgettable desert adventure that blends adrenaline, tradition, and culture. Speed across golden dunes on a quad bike, then slow down to enjoy a peaceful camel ride under the vast desert sky. As the sun sets, immerse yourself in Bedouin hospitality with a traditional dinner, followed by an enchanting folkloric show of music and dance. This experience combines thrill, serenity, and authentic desert life all in one magical evening.', '/trips/ultimate-desert-experience-quad-biking-camel-ride-bedouin-dinner-and-show.png', 42, 'USD', NULL, 0, 0, 1, 62, 10, 'Economy', 'legacy', 1, '{"source":"legacyCatalog","sourceCities":["Sharm El Sheikh"],"sourceCategories":["Adventure Trips","Family Friendly","One Day Trips"]}') ON DUPLICATE KEY UPDATE title = VALUES(title), city_id = VALUES(city_id), location_label = VALUES(location_label), category_id = VALUES(category_id), duration_label = VALUES(duration_label), duration_minutes = VALUES(duration_minutes), description = VALUES(description), image_url = VALUES(image_url), price_from = VALUES(price_from), currency = VALUES(currency), rating = VALUES(rating), review_count = VALUES(review_count), is_featured = VALUES(is_featured), is_active = 1, solo_price = VALUES(solo_price), discount_percent = VALUES(discount_percent), price_level = VALUES(price_level), source_type = VALUES(source_type), catalog_visible = VALUES(catalog_visible), metadata = VALUES(metadata);
