INSERT INTO trips (id, slug, title, city_id, location_label, category_id, duration_label, duration_minutes, description, image_url, price_from, currency, rating, review_count, is_featured, is_active, solo_price, discount_percent, price_level, source_type, catalog_visible, metadata) VALUES ('0aa68c34-7ebd-41db-a582-f9be52217454', 'tour-of-valley-of-the-nobles-medinat-habu-and-the-ramesseum-from-luxor', 'Tour of Valley of the Nobles, Medinat Habu and The Ramesseum from Luxor', (SELECT id FROM cities WHERE slug = 'luxor' LIMIT 1), 'Luxor', (SELECT id FROM trip_categories WHERE slug = 'one-day-trips' LIMIT 1), '1 day', 1440, 'Whether it is your first-time visiting Luxor or you have done it before, this experience is for you. Discover the legends of the Nobles Valley and the legendary Temple of Habu plus the captivating Ramesseum Temple. Starting from meeting your guide Egyptologist at the lobby of your hotel or Nile Cruises, you''ll travel towards Luxor West Bank passing by the Luxor Bridge until reaching the staggering Colossi of Memnon, and two 60-foot stone statues that have stood for more than 3,000 years. Marvel at the Valley of Nobles with its hundreds of rock-cut tombs carved in the hillside. Then, you''ll see one of Egypt’s best-preserved and most interesting temples called Medinat Habu, whilst hearing how it''s one of the few monuments in Egypt to convey the emotional impact that religious art and architecture must have had on the ancient Egyptians. Next, at the Ramesseum, you''ll explore what Amelia Edwards wrote as "the warm limestone of which it is built seems to have mellowed and turned golden with time. No walls enclose it. No towering pylons overshadow it. It stands high, and the air circulated freely”.', '/trips/tour-of-valley-of-the-nobles-medinat-habu-and-the-ramesseum-from-luxor.png', 74, 'USD', NULL, 0, 0, 1, 107, 0, 'Economy', 'legacy', 1, '{"source":"legacyCatalog","sourceCities":["Luxor"],"sourceCategories":["One Day Trips","Adventure Trips","Family Friendly"]}') ON DUPLICATE KEY UPDATE title = VALUES(title), city_id = VALUES(city_id), location_label = VALUES(location_label), category_id = VALUES(category_id), duration_label = VALUES(duration_label), duration_minutes = VALUES(duration_minutes), description = VALUES(description), image_url = VALUES(image_url), price_from = VALUES(price_from), currency = VALUES(currency), rating = VALUES(rating), review_count = VALUES(review_count), is_featured = VALUES(is_featured), is_active = 1, solo_price = VALUES(solo_price), discount_percent = VALUES(discount_percent), price_level = VALUES(price_level), source_type = VALUES(source_type), catalog_visible = VALUES(catalog_visible), metadata = VALUES(metadata);
INSERT INTO trip_day_plans (trip_id, day_number, activities) VALUES ((SELECT id FROM trips WHERE slug = 'tour-of-valley-of-the-nobles-medinat-habu-and-the-ramesseum-from-luxor' LIMIT 1), 1, '[{"time":"08:00","title":"Meet your Egyptologist guide at your hotel or Nile Cruise lobby."},{"time":"12:15","title":"Tour the Ramesseum, the mortuary temple of Ramses II, admired for its golden limestone and open design."},{"time":"14:00","title":"End of the tour."}]') ON DUPLICATE KEY UPDATE activities = VALUES(activities);
INSERT INTO trip_inclusions (trip_id, item, sort_order) VALUES ((SELECT id FROM trips WHERE slug = 'tour-of-valley-of-the-nobles-medinat-habu-and-the-ramesseum-from-luxor' LIMIT 1), 'Entrance tickets to 2 tombs at the Nobel’s Valley and Habu Temple plus the Ramesseum Temple.', 0) ON DUPLICATE KEY UPDATE sort_order = VALUES(sort_order);
