INSERT INTO trips (id, slug, title, city_id, location_label, category_id, duration_label, duration_minutes, description, image_url, price_from, currency, rating, review_count, is_featured, is_active, solo_price, discount_percent, price_level, source_type, catalog_visible, metadata) VALUES ('a504f676-4f38-44f5-8a06-fa8edbeaf3cc', 'discover-the-grand-museum-and-giza-pyramids-by-plane-from-sharm-el-sheikh', 'Discover The Grand Museum and Giza Pyramids by Plane from Sharm El Sheikh', (SELECT id FROM cities WHERE slug = 'cairo' LIMIT 1), 'Cairo · Sharm El Sheikh', (SELECT id FROM trip_categories WHERE slug = 'historical' LIMIT 1), '1 day', 1440, 'Be one of the first visitors to experience the New Grand Egyptian Museums (GEM) set to be the world''s largest archaeological museum dedicated to a single civilization. It houses over 100,000 artefacts from ancient Egypt. It is designed to provide a modern context for historical artefacts, featuring permanent and temporary exhibition spaces, a children''s museum, conference facilities, and extensive gardens. Your experience will be completed by visiting the Giza Pyramids, the world''s most iconic and ancient structures. You''ll be picked up from your accommodation in Sharm El Sheikh to reach the airport and fly to Cairo, from where you''ll be driven to the Giza Pyramids. Admire the last remaining wonder of the ancient world before standing in awe beneath the Great Sphinx. Next, you''ll enjoy a delicious lunch at a local restaurant. Entering the Grand Egyptian Museum, you''ll then start the journey of the Egyptian kings to eternity. Ascend the Grand Staircase, surrounded by a precisely curated collection of 64 monumental treasures from the most illustrious past, and let the mysteries of ancient Egypt unveil before your eyes. Then enter the fascinating Hall of Tutankhamun Treasures, home to the most extensive collection ever displayed from the young king’s tomb. Its immersive showcases reveal the craftsmanship, rituals, and royal splendour of the 18th Dynasty. Each work of art and remains is a piece of the intricate puzzle that once was ancient Egypt’s fascinating civilization. Prepare yourself to discover Egypt''s most prized possessions.', '/trips/discover-the-grand-museum-and-giza-pyramids-by-plane-from-sharm-el-sheikh.png', 177, 'USD', NULL, 0, 0, 1, 247, 0, 'Standard', 'legacy', 1, '{"source":"legacyCatalog","sourceCities":["Cairo","Sharm El Sheikh"],"sourceCategories":["Historical","Luxury Tours","Family Friendly","One Day Trips"]}') ON DUPLICATE KEY UPDATE title = VALUES(title), city_id = VALUES(city_id), location_label = VALUES(location_label), category_id = VALUES(category_id), duration_label = VALUES(duration_label), duration_minutes = VALUES(duration_minutes), description = VALUES(description), image_url = VALUES(image_url), price_from = VALUES(price_from), currency = VALUES(currency), rating = VALUES(rating), review_count = VALUES(review_count), is_featured = VALUES(is_featured), is_active = 1, solo_price = VALUES(solo_price), discount_percent = VALUES(discount_percent), price_level = VALUES(price_level), source_type = VALUES(source_type), catalog_visible = VALUES(catalog_visible), metadata = VALUES(metadata);
INSERT INTO trip_day_plans (trip_id, day_number, activities) VALUES ((SELECT id FROM trips WHERE slug = 'discover-the-grand-museum-and-giza-pyramids-by-plane-from-sharm-el-sheikh' LIMIT 1), 1, '[{"time":"06:00","title":"1‑hour flight to Cairo. Meet your representative and Egyptologist guide upon arrival."},{"time":"07:30","title":"Enjoy a delicious meal at a local restaurant in Cairo."}]') ON DUPLICATE KEY UPDATE activities = VALUES(activities);
