INSERT INTO trips (id, slug, title, city_id, location_label, category_id, duration_label, duration_minutes, description, image_url, price_from, currency, rating, review_count, is_featured, is_active, solo_price, discount_percent, price_level, source_type, catalog_visible, metadata) VALUES ('24eff393-24c5-4160-adcd-fb640c74f028', 'abu-simbel-day-trip-from-aswan-round-trip-by-car', 'Abu Simbel Day Trip from Aswan – Round Trip by Car', (SELECT id FROM cities WHERE slug = 'aswan' LIMIT 1), 'Aswan', (SELECT id FROM trip_categories WHERE slug = 'spiritual' LIMIT 1), '1 day', 1440, 'Explore one of Egypt''s most iconic ancient wonders on a full-day round trip from Aswan to Abu Simbel. Discover the grandeur of the Great Temple of Ramses II and the Temple of Queen Nefertari, both carved into the mountainside overlooking Lake Nasser. This historical adventure offers the perfect balance of cultural discovery and scenic desert drive. Whether you''re solo or part of a group, this tour is designed for comfort and unforgettable moments with WasetTravel ! Book 24 hours in advance to secure your place.', '/trips/abu-simbel-day-trip-from-aswan-round-trip-by-car.png', 77, 'USD', NULL, 0, 0, 1, 117, 10, 'Economy', 'legacy', 1, '{"source":"legacyCatalog","sourceCities":["Aswan"],"sourceCategories":["Spiritual","One Day Trips"]}') ON DUPLICATE KEY UPDATE title = VALUES(title), city_id = VALUES(city_id), location_label = VALUES(location_label), category_id = VALUES(category_id), duration_label = VALUES(duration_label), duration_minutes = VALUES(duration_minutes), description = VALUES(description), image_url = VALUES(image_url), price_from = VALUES(price_from), currency = VALUES(currency), rating = VALUES(rating), review_count = VALUES(review_count), is_featured = VALUES(is_featured), is_active = 1, solo_price = VALUES(solo_price), discount_percent = VALUES(discount_percent), price_level = VALUES(price_level), source_type = VALUES(source_type), catalog_visible = VALUES(catalog_visible), metadata = VALUES(metadata);
