":"Double bedroom with balcony doors"},{"index":3,"label":"Bedroom","alt":"Bright bedroom with balcony access and ensuite doorway"},{"index":4,"label":"Villa exterior","alt":"Habu Sunset Villa exterior facade"},{"index":5,"label":"Bedroom detail","alt":"Double bed with crisp white linens and warm wall lights"},{"index":6,"label":"Bedroom seating","alt":"Bedroom with bed, armchair and television"},{"index":7,"label":"Open-plan living","alt":"Open-plan living area and kitchen with pendant lights"},{"index":8,"label":"Living room","alt":"Living room with sofas, rugs and kitchen"},{"index":9,"label":"Twin bedroom","alt":"Twin beds beside a bright balcony"},{"index":10,"label":"Family bedroom","alt":"Bedroom with double and single beds"},{"index":11,"label":"Twin room","alt":"Twin room with wardrobes and curtains"},{"index":12,"label":"Pool terrace","alt":"Private pool terrace with sun loungers"},{"index":13,"label":"Living and kitchen","alt":"Open-plan sitting room and kitchen"},{"index":14,"label":"Kitchen and bath","alt":"Kitchen beside a marble bathroom vanity"},{"index":15,"label":"Bedroom and bath","alt":"Bedroom view through the bathroom doorway"},{"index":16,"label":"Kitchen detail","alt":"Kitchen appliances beside the bathroom"},{"index":17,"label":"Kitchen view","alt":"Bedroom, bathroom and kitchenette from one angle"},{"index":18,"label":"Pool close-up","alt":"Blue swimming pool with loungers and umbrella"},{"index":19,"label":"Balcony view","alt":"Private balcony with two chairs overlooking the neighborhood"},{"index":20,"label":"Pool terrace wide","alt":"Wide pool terrace with loungers"},{"index":21,"label":"Balcony seating","alt":"Balcony seating with a view over the neighborhood"},{"index":22,"label":"Pool and villa","alt":"Villa facade beside the private pool"},{"index":23,"label":"Bathroom","alt":"Marble bathroom with walk-in shower and vanity"},{"index":24,"label":"Pool shade","alt":"Pool terrace with large umbrella and loungers"},{"index":25,"label":"P