INSERT INTO stays (id, slug, name, city_id, location_label, stay_type, description, image_url, price_from, currency, rating, review_count, amenities, max_guests, is_featured, is_active, metadata) VALUES ('2a9e3029-4896-5507-a67e-35bdfd01c865', 'red-sea-garden-villa', 'Red Sea Garden Villa', (SELECT id FROM cities WHERE slug = 'egypt' LIMIT 1), 'Hurghada, Egypt', 'villa', 'An open villa stay for sun, space and a slower route to the Red Sea.', '/alpnile-stays-hotels-hero.webp', 165, 'USD', 4.8, 24, '["Red Sea snorkelling","Intro scuba dive","Desert safari","Sunset sailing"]', 6, 0, 0, '{"slug":"red-sea-garden-villa","title":"Red Sea Garden Villa","kind":"Villa","location":"Hurghada, Egypt","rating":"4.8","reviews":24,"price":165,"guests":6,"bedrooms":3,"baths":2,"image":"/alpnile-stays-hotels-hero.webp","description":"An open villa stay for sun, space and a slower route to the Red Sea.","available":false,"coordinates":{"lat":27.2579,"lng":33.8116},"mapLabel":"Hurghada, Red Sea","mapsUrl":"https://www.google.com/maps/search/?api=1&query=27.2579%2C33.8116","activities":[{"id":"hurghada-snorkel","icon":"boat","title":"Red Sea snorkelling","detail":"Clear water, coral and a local boat crew","duration":"Half day","price":55},{"id":"hurghada-diving","icon":"pool","title":"Intro scuba dive","detail":"A guided first dive for beginners","duration":"Half day","price":85},{"id":"hurghada-safari","icon":"horse","title":"Desert safari","detail":"Quad bikes, tea and a Bedouin sunset","duration":"5 hours","price":48},{"id":"hurghada-sunset","icon":"sun","title":"Sunset sailing","detail":"A soft evening on the Red Sea","duration":"2 hours","price":42}],"blockedDates":["2026-12-07","2026-12-08","2026-12-09","2026-12-20","2026-12-21","2026-12-22"],"gallery":[{"index":131,"label":"Villa exterior","alt":"Red Sea garden villa","source":"/alpnile-stays-hotels-hero.webp"},{"index":132,"label":"Pool day","alt":"Red Sea pool day","source":"/alpnile-hero-beach-3d-v2.webp"},{"index":133,"label"