INSERT INTO stays (id, slug, name, city_id, location_label, stay_type, description, image_url, price_from, currency, rating, review_count, amenities, max_guests, is_featured, is_active, metadata) VALUES ('4efdcd9e-662f-59b1-9943-f1882b343cd1', 'riverside-suite', 'Riverside Residence Suite', (SELECT id FROM cities WHERE slug = 'egypt' LIMIT 1), 'Luxor, Egypt', 'hotel_room', 'A spacious river-facing suite for travelers who want a soft landing between ancient sites.', '/alpnile-hotel-luxor-riverside.webp', 190, 'USD', 4.8, 27, '["Felucca at sunset","Balloon over Luxor","Banana Island lunch","Temple route"]', 3, 0, 0, '{"slug":"riverside-suite","title":"Riverside Residence Suite","kind":"Hotel room","location":"Luxor, Egypt","rating":"4.8","reviews":27,"price":190,"guests":3,"bedrooms":1,"baths":1,"image":"/alpnile-hotel-luxor-riverside.webp","description":"A spacious river-facing suite for travelers who want a soft landing between ancient sites.","available":false,"coordinates":{"lat":25.6872,"lng":32.6396},"mapLabel":"Luxor Corniche","mapsUrl":"https://www.google.com/maps/search/?api=1&query=25.6872%2C32.6396","activities":[{"id":"riverside-felucca","icon":"boat","title":"Felucca at sunset","detail":"A private sail from the riverfront","duration":"2 hours","price":30},{"id":"riverside-balloon","icon":"balloon","title":"Balloon over Luxor","detail":"A sunrise flight across the West Bank","duration":"3 hours","price":75},{"id":"riverside-banana","icon":"sun","title":"Banana Island lunch","detail":"An easy island day with local food","duration":"Half day","price":45},{"id":"riverside-temples","icon":"map","title":"Temple route","detail":"Karnak, Luxor and the stories between them","duration":"4 hours","price":40}],"blockedDates":["2026-12-16","2026-12-17","2026-12-24"],"gallery":[{"index":141,"label":"Riverside suite","alt":"Luxor riverside suite","source":"/alpnile-hotel-luxor-riverside.webp"},{"index":142,"label":"Evening river","alt":"Nile river evening","source":"/al